 21→	let sessionId = $derived($page.params.id);
 22→
 23→	let session = $state<SessionDetail | null>(null);
 24→	let events = $state<SessionEventType[]>([]);
 25→	let blocks = $state<DisplayBlock[]>([]);
 26→	let loading = $state(true);
 27→	let error = $state('');
 28→
 29→	// AC: @ui-session-stream ac-2 — Live streaming state
 30→	let streamingText = $state('');
 31→	let isLive = $derived(session?.status === 'active');
 32→	let lastSeq = $state(-1);
 33→	let refreshTimer: ReturnType<typeof setInterval> | undefined;
 34→
 35→	async function loadSession() {
 36→		loading = true;
 37→		error = '';
 38→		try {
 39→			const [sessionData, eventsData] = await Promise.all([
 40→				fetchSession(sessionId),
 41→				fetchSessionEvents(sessionId)
 42→			]);
 43→			session = sessionData;
 44→			events = eventsData.events;
 45→			blocks = parseEventsToBlocks(events);
 46→			lastSeq = getLastSeq(events);
 47→		} catch (err) {
 48→			error = err instanceof Error ? err.message : 'Failed to load session';
 49→		} finally {
 50→			loading = false;
 51→		}
 52→	}
 53→
 54→	// AC: @ui-session-stream ac-2 — Periodic structured refresh for live sessions
 55→	async function refreshEvents() {
 56→		if (!isLive) return;
 57→		try {
 58→			const eventsData = await fetchSessionEvents(sessionId, lastSeq);
 59→			if (eventsData.events.length > 0) {
 60→				events = [...events, ...eventsData.events];
 61→				blocks = parseEventsToBlocks(events);
 62→				lastSeq = getLastSeq(events);
 63→				// Clear streaming text when we get structured data
 64→				streamingText = '';
 65→			}
 66→
 67→			// Also refresh session metadata to detect status changes
 68→			const sessionData = await fetchSession(sessionId);
 69→			session = sessionData;
 70→		} catch {
 71→			// Ignore refresh errors — will retry on next interval
 72→		}
 73→	}
 74→
 75→	// AC: @ui-session-stream ac-2 — WebSocket handler for live text chunks
 76→	function handleAgentEvent(event: BroadcastEvent) {
 77→		// Uses extracted utility for session-filtered text accumulation
 78→		streamingText = accumulateStreamingText(streamingText, event, sessionId);
 79→
 80→		if (event.event === 'agent_invocation') {
 81→			const data = event.data as { session_id?: string; status?: string };
 82→			if (data.session_id === sessionId) {
 83→				// Refresh on invocation state changes
 84→				refreshEvents();
 85→			}
 86→		}
 87→	}
 88→
 89→	onMount(() => {
 90→		loadSession();
 91→
 92→		// Subscribe to agent events for live streaming
 93→		subscribe(['agents']);
 94→		on('agents', handleAgentEvent);
 95→
 96→		// AC: @ui-session-stream ac-2 — Periodic refresh (every 3s for live sessions)
 97→		refreshTimer = setInterval(() => {
 98→			if (isLive) {
 99→				refreshEvents();
100→			}
101→		}, 3000);
102→	});
103→
104→	onDestroy(() => {
105→		off('agents', handleAgentEvent);
106→		unsubscribe(['agents']);
107→		if (refreshTimer) clearInterval(refreshTimer);
108→	});
