     3→  AC: @ui-session-stream ac-2 — Live streaming via WebSocket agent_text_chunk events.
     4→  AC: @ui-session-stream ac-3 — Auto-scroll with jump-to-bottom.
     5→  AC: @ui-session-stream ac-4 — Session context panel with metadata.
     6→-->
     7→<script lang="ts">
     8→	import { page } from '$app/stores';
     9→	import { onMount, onDestroy } from 'svelte';
    10→	import type { SessionDetail, SessionEvent as SessionEventType } from '$lib/api';
    11→	import { fetchSession, fetchSessionEvents } from '$lib/api';
    12→	import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
    13→	import type { BroadcastEvent } from '@kynetic-ai/shared';
    14→	import { parseEventsToBlocks, accumulateStreamingText, getLastSeq, type DisplayBlock } from '$lib/components/session/session-utils';
    15→	import SessionStream from '$lib/components/session/SessionStream.svelte';
    16→	import SessionContextPanel from '$lib/components/session/SessionContextPanel.svelte';
    17→	import SessionStreamSkeleton from '$lib/components/session/SessionStreamSkeleton.svelte';
    18→	import ArrowLeft from '@lucide/svelte/icons/arrow-left';
    19→	import { base } from '$app/paths';
