   118→		>
   119→			<ArrowLeft class="size-4" />
   120→		</a>
   121→		<div>
   122→			<h1 class="text-lg font-semibold">
   123→				Session
   124→				{#if session}
   125→					<span class="font-mono text-sm text-muted-foreground ml-1">{session.id.slice(0, 8)}</span>
   126→				{/if}
   127→			</h1>
   128→			{#if session}
   129→				<p class="text-xs text-muted-foreground">
   130→					{session.agent_type}
   131→					{#if isLive}
   132→						<span class="ds-session-active-dot size-1.5 rounded-full bg-status-completed inline-block ml-1"></span>
   133→						<span class="text-status-completed">Live</span>
   134→					{/if}
   135→				</p>
   136→			{/if}
   137→		</div>
   138→	</div>
